        chacha_block(k,counter,n,block);
        for(int i=0;i<16;i++){
            uint32_t ks = block[i];
            uint32_t p;
            memcpy(&p, in+i*4, 4);
            uint32_t c = p ^ ks;
            memcpy(out+i*4, &c, 4);
        }
        in+=64; out+=64; len-=64; counter++;
    }
